INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r4','','wei-weiguo','["卫疌伯"]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','嗣伯之后，子继立，称疌伯；其本名未见史籍记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫疌伯"}]','疌',NULL,'疌伯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r40','训','wei-weiguo','["卫声公"]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','慎公之子训，谥声公，在位十一年，承续卫国世系，事迹记载有限，事见《史记》本国世家记载。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫声公"}]','声',NULL,'声公','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r41','遫','wei-weiguo','["卫成侯"]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫成侯（姬遫），卫声公之子，前371–前343年在位。前346年卫国自贬为侯，臣服韩、赵、魏。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫成侯"}]','成',NULL,'成侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r42','劲','wei-weiguo','["卫平侯"]','姬','子南',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫平侯（姬劲），姬姓子南氏，卫灵公少子公子郢之后；前342–前335年在位。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫平侯"}]','平',NULL,'平侯','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r43','','wei-weiguo','[]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫嗣君在位期间卫国已收缩为战国小国，夹处魏、赵、韩等强邻之间；关于其个人改革与外交，现存材料记载不一，本库仅保留可相互印证的世系信息。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫嗣君"},{"label":"《史记·卫康叔世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷037"},{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"}]','嗣',NULL,'嗣君','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r44','','wei-weiguo','[]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫怀君承卫嗣君而立，卫国此时仍以濮阳一带为中心，国势受魏国制约；其本名不见于可靠史料，统治细节也无从确考。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫怀君"}]','怀',NULL,'怀君','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r45','','wei-weiguo','[]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫元君姬姓、子南氏，承卫怀君之后在位。卫国末期依附魏国，秦统一后改为秦的东郡；君主本名失载，个人政事记录有限。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/卫元君"}]','元',NULL,'元君','[]');
INSERT INTO "persons" ("id","name","dynasty_id","alt_names","ancestral_xing","clan_shi","birth_year","birth_month","birth_day","birth_confidence","death_year","death_month","death_day","death_confidence","roles","bio","links","posthumous_name","temple_name","title","search_terms") VALUES ('weiguo-r46','角','wei-weiguo','[]','姬','卫',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'["君主"]','卫国末代君主，未得谥号，前209年秦废卫君角为庶人，卫国至此灭亡，比秦统一早九年。','[{"label":"维基百科","url":"https://zh.wikipedia.org/wiki/君角"}]',NULL,NULL,'君角','[]');
