INSERT INTO "events" ("id","name","kind","time_mode","at_confidence","start_confidence","end_confidence","date_note","at_year","at_month","at_day","at_abs","start_year","start_month","start_day","start_abs","end_year","end_month","end_day","end_abs","summary","meaning","content","links") VALUES ('wei-si-demotes-to-jun','卫嗣君贬号为君','politics','point','approximate_year',NULL,NULL,'《史记·卫康叔世家》嗣君五年；此处采前330年，嗣君纪年有异说，《资治通鉴》系于前320年，故用约年。',-330,12,NULL,-3937,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'约-330年，卫嗣君将称号由侯降为君。《史记》把这次贬号与“独有濮阳”并记：卫在大国兼并中领土缩小，难以维持原有诸侯地位。改称君反映国势衰落后的名号调整，此后的卫君继续依存于战国强国之间；这里的“君”不是周代五等爵之外另设的一等爵。',NULL,NULL,'[{"label":"《史记·卫康叔世家》","url":"https://zh.wikisource.org/zh-hans/史記/卷037"},{"label":"《资治通鉴》卷3","url":"https://zh.wikisource.org/zh-hans/資治通鑑/卷003"}]');
